    if (window.PG_MENU_LAYOUT_CONFIG && window.PG_MENU_LAYOUT_CONFIG.isLayoutB()) {
      if (t === '본사설정' || t === '본사 정책') t = '본사정책';
      if (t === '배포설정') t = '연동·배포';
    }
