  function applyCommissionListColumnPercents(table, cols) {
    if (!table || !cols || !cols.length) return;
    var FIXED = {
      _chk: 2,
      rowNo: 3,
      compNm: 12,
      compId: 7,
      policyCur: 4,
      inlineActions: 7,
      applyDt: 7
    };
    var fixedSum = 0;
    var flexIdx = [];
    var widths = [];
    cols.forEach(function (c, i) {
      var key = c && c.key ? String(c.key) : '';
      if (c && c.type === 'checkbox') key = '_chk';
      if (c && c.type === 'commissionInlineActions') key = 'inlineActions';
      if (Object.prototype.hasOwnProperty.call(FIXED, key)) {
        widths[i] = FIXED[key];
        fixedSum += FIXED[key];
      } else {
        widths[i] = null;
        flexIdx.push(i);
      }
    });
    if (fixedSum > 100) fixedSum = 100;
    var remain = Math.max(0, 100 - fixedSum);
    if (flexIdx.length === 0) {
      /* 가변 열이 없으면 고정열만 비율 재정규화 */
      if (fixedSum > 0 && fixedSum !== 100) {
        var scale = 100 / fixedSum;
        for (var si = 0; si < widths.length; si++) {
          if (widths[si] != null) widths[si] = Math.round(widths[si] * scale * 1000) / 1000;
        }
      }
    } else {
      var each = remain / flexIdx.length;
      flexIdx.forEach(function (fi) {
        widths[fi] = Math.round(each * 1000) / 1000;
      });
    }
    var old = table.querySelector('colgroup.commission-pct-colgroup');
    if (old) old.parentNode.removeChild(old);
    var cg = document.createElement('colgroup');
    cg.className = 'commission-pct-colgroup';
    widths.forEach(function (w) {
      var col = document.createElement('col');
      if (w != null && isFinite(w)) col.style.width = w + '%';
      cg.appendChild(col);
    });
    table.insertBefore(cg, table.firstChild);
  }
  function resolveViewSettingHelloPriorityKeys(pageUrl, pane) {
    var screens = window.PG_SCREENS && typeof window.PG_SCREENS.getMenuScreens === 'function'
      ? window.PG_SCREENS.getMenuScreens() : null;
    var cfg = (screens && pageUrl && screens[pageUrl]) ? screens[pageUrl] : null;
    if (pane && pane._payListMergedCfg && pane._payListMergedCfg.viewSettingHelloPriorityKeys) {
      return pane._payListMergedCfg.viewSettingHelloPriorityKeys.slice();
    }
    if (cfg && cfg.viewSettingHelloPriorityKeys && cfg.viewSettingHelloPriorityKeys.length) {
      return cfg.viewSettingHelloPriorityKeys.slice();
    }
    if (pageUrl === '/calc/payOverview') {
      var O = window.PG_PAY_LIST_OVERVIEW;
      if (O && O.viewSettingHelloPriorityKeys && O.viewSettingHelloPriorityKeys.length) {
        return O.viewSettingHelloPriorityKeys.slice();
      }
    }
    if (pageUrl === '/calc/jpayTrList') {
      var JO = window.PG_JPAY_TR_OVERVIEW;
      if (JO && JO.viewSettingHelloPriorityKeys && JO.viewSettingHelloPriorityKeys.length) {
        return JO.viewSettingHelloPriorityKeys.slice();
      }
    }
    if (typeof PAY_LIST_NOTIFY_LAYOUT_URLS !== 'undefined' && PAY_LIST_NOTIFY_LAYOUT_URLS.indexOf(pageUrl) !== -1) {
      var P = window.PG_PAY_LIST_INTEGRATED;
      if (P && P.viewSettingHelloPriorityKeys && P.viewSettingHelloPriorityKeys.length) {
        return P.viewSettingHelloPriorityKeys.slice();
      }
    }
    if (pageUrl === '/calc/feeList' || pageUrl === '/settlement/feeList') {
      var screensFeeHello = window.PG_SCREENS && typeof window.PG_SCREENS.getMenuScreens === 'function'
        ? window.PG_SCREENS.getMenuScreens() : null;
      var feeHelloCfg = screensFeeHello && screensFeeHello['/calc/feeList'];
      if (feeHelloCfg && feeHelloCfg.viewSettingHelloPriorityKeys && feeHelloCfg.viewSettingHelloPriorityKeys.length) {
        return feeHelloCfg.viewSettingHelloPriorityKeys.slice();
      }
      if (feeHelloCfg && feeHelloCfg.viewSettingDefaultSelectedKeys && feeHelloCfg.viewSettingDefaultSelectedKeys.length) {
        return feeHelloCfg.viewSettingDefaultSelectedKeys.slice();
      }
    }
    if (pageUrl === '/ops/agencyTxnList') {
      var screensAgHello = window.PG_SCREENS && typeof window.PG_SCREENS.getMenuScreens === 'function'
        ? window.PG_SCREENS.getMenuScreens() : null;
      var agHelloCfg = screensAgHello && screensAgHello['/ops/agencyTxnList'];
      if (agHelloCfg && agHelloCfg.viewSettingHelloPriorityKeys && agHelloCfg.viewSettingHelloPriorityKeys.length) {
        return agHelloCfg.viewSettingHelloPriorityKeys.slice();
      }
      if (agHelloCfg && agHelloCfg.viewSettingDefaultSelectedKeys && agHelloCfg.viewSettingDefaultSelectedKeys.length) {
        return agHelloCfg.viewSettingDefaultSelectedKeys.slice();
      }
    }
    return null;
  }
  function pgHelloSyncButtonForPane(pane, hidden) {
    if (!pane || !pane.id) return;
    var viewHelloBtn = document.getElementById('viewSettingHelloBtn_' + pane.id);
    if (!viewHelloBtn) return;
    viewHelloBtn.classList.toggle('btn-view-setting-hello--restore', !!hidden);
    viewHelloBtn.setAttribute('aria-pressed', hidden ? 'true' : 'false');
    var tlOn = pgHelloTimelineIsEnabled();
    var baseHidden = hidden
      ? '클릭 시 안내(파스텔)·VIEW SETTING을 다시 표시합니다.'
      : '클릭 시 안내(파스텔)·VIEW SETTING을 숨깁니다.';
    if (tlOn) {
      var u = pgHelloTimelineUntilMs();
      if (u > Date.now()) {
        var sec = Math.ceil((u - Date.now()) / 1000);
        var mm = Math.floor(sec / 60);
        var ss = sec % 60;
        viewHelloBtn.title = (hidden ? '안내 숨김' : '안내 표시') + ' — 헬로 타임라인 약 ' + mm + '분 ' + ss + '초 남음 (전 페이지 동기)';
      } else {
        viewHelloBtn.title = (hidden ? '안내 숨김(기본)' : '안내 표시') + ' — 헬로 타임라인: 클릭 시 전 페이지에 ' +
          ((window._pgHelloTimelineFromLedger && window._pgHelloTimelineFromLedger.helloTimelineDurationMin) || 10) + '분 동안 표시';
      }
    } else {
      viewHelloBtn.title = baseHidden;
    }
  }
  function pgHelloApplyTimelineToAllPanes(hidden) {
    document.querySelectorAll('.tab-pane').forEach(function (p) {
      if (!p || !p.querySelector) return;
      if (!p.querySelector('[id^="viewSettingHelloBtn_"]')) return;
      p._viewSettingHelloHidden = !!hidden;
      pgHelloZonesSetHidden(p, hidden);
      pgHelloSyncButtonForPane(p, hidden);
    });
    try {
      if (window.PG_TABLE_COL_RESIZE && typeof window.PG_TABLE_COL_RESIZE.refreshInSync === 'function') {
        document.querySelectorAll('.tab-pane').forEach(function (p) { window.PG_TABLE_COL_RESIZE.refreshInSync(p); });
      } else if (window.PG_TABLE_COL_RESIZE && typeof window.PG_TABLE_COL_RESIZE.refreshIn === 'function') {
        document.querySelectorAll('.tab-pane').forEach(function (p) { window.PG_TABLE_COL_RESIZE.refreshIn(p); });
      }
    } catch (eR) { /* ignore */ }
  }
  function pgHelloTimelineTick() {
    if (!pgHelloTimelineIsEnabled()) return;
    var u = pgHelloTimelineUntilMs();
    if (u > 0 && u <= Date.now()) {
      pgHelloTimelineSetUntilMs(0);
      pgHelloApplyTimelineToAllPanes(true);
      return;
    }
    if (u > Date.now()) {
      document.querySelectorAll('.tab-pane').forEach(function (p) {
        if (p.querySelector && p.querySelector('[id^="viewSettingHelloBtn_"]') && !p._viewSettingHelloHidden) {
          pgHelloSyncButtonForPane(p, false);
        }
      });
    }
  }
  if (!window._pgHelloTimelineTickStarted) {
    window._pgHelloTimelineTickStarted = true;
    setInterval(pgHelloTimelineTick, 15000);
  }
  try {
    window.pgHelloTimelineInvalidateConfigCache = pgHelloTimelineInvalidateConfigCache;
    window.pgHelloTimelineFetchConfig = pgHelloTimelineFetchConfig;
    window.pgHelloApplyTimelineToAllPanes = pgHelloApplyTimelineToAllPanes;
  } catch (eHT) { /* ignore */ }

  /**
   * 가맹점 수수료 정책 목록 등: 건당·고정액·% 셀 표시(통화 구분 없이 동일 규칙).
   * currencyCode는 호환용으로만 받으며 포맷에는 사용하지 않음.
   */
  function pgFmtPolicyListAmount(v, currencyCode) {
    var out = pgFmtOneDecimalStripWhole(v == null || v === '' ? '0' : v);
    return out === '' ? '0' : out;
  }

  /** 업체 등록·상세: 동일 name 이 숨김 카드·노출 카드에 중복될 때 모두 반영 (querySelector 단일 매칭 오류 방지) */
  function pgSetCompFormFieldValues(form, name, value) {
    if (!form || !name || value == null) return;
    var nf = pgFmtCompDetailNumericField(name, value);
    var v = nf != null ? nf : value;
    form.querySelectorAll('[name="' + name + '"]').forEach(function (el) {
      if (el.type === 'file') return;
      el.value = v;
    });
  }

  /** 영업정보/기타 — DB addrEtc 저장 형식: ONLINE|… / OFFLINE|… / OTHER|… */
  function pgParseSalesInfoAddrEtc(raw) {
    var s = String(raw == null ? '' : raw).trim();
    var m = /^(ONLINE|OFFLINE|OTHER)\|(.*)$/i.exec(s);
    if (m) {
      return { type: String(m[1]).toUpperCase(), detail: m[2] != null ? String(m[2]) : '' };
    }
    if (!s) return { type: '', detail: '' };
    if (/^https?:\/\//i.test(s) || /^(www\.)?[a-z0-9][-a-z0-9.]*\.[a-z]{2,}(\/|$)/i.test(s)) {
      return { type: 'ONLINE', detail: s };
    }
    return { type: 'OTHER', detail: s };
  }

  function pgEncodeSalesInfoAddrEtc(type, detail) {
    var t = String(type || '').trim().toUpperCase();
    if (!t) return String(detail || '').trim();
    return t + '|' + String(detail || '').trim();
  }

  function pgSalesInfoPlaceholderKey(type) {
    var t = String(type || '').toUpperCase();
    if (t === 'ONLINE') return '도메인 입력 (예: example.com)';
    if (t === 'OFFLINE') return '상호명 (마트·클럽 등)';
    if (t === 'OTHER') return '선택 입력';
    return '도메인 또는 상호명';
  }

  function pgSyncSalesInfoUi(form) {
    if (!form) return;
    form.querySelectorAll('[data-sales-info-wrap]').forEach(function (wrap) {
      var typeEl = wrap.querySelector('[data-sales-info-type], [name="salesInfoType"]');
      var detEl = wrap.querySelector('[data-sales-info-detail], [name="addrEtc"]');
      if (!typeEl || !detEl) return;
      var t = String(typeEl.value || '').toUpperCase();
      var phKey = pgSalesInfoPlaceholderKey(t);
      detEl.placeholder = pgAdminUiT(phKey);
      detEl.setAttribute('data-pg-ui-placeholder', phKey);
      var needDetail = (t === 'ONLINE' || t === 'OFFLINE');
      detEl.classList.toggle('required-input', needDetail);
      if (t === 'OTHER') detEl.classList.remove('required-input');
    });
  }

  function pgApplySalesInfoFieldsFromAddrEtc(form, rawAddrEtc) {
    if (!form) return;
    var wrap = form.querySelector('[data-sales-info-wrap]');
    if (!wrap) return;
    var parsed = pgParseSalesInfoAddrEtc(rawAddrEtc);
    var typeEl = wrap.querySelector('[name="salesInfoType"]');
    var detEl = wrap.querySelector('[name="addrEtc"]');
    if (typeEl) typeEl.value = parsed.type || '';
    if (detEl) detEl.value = parsed.detail || '';
    pgSyncSalesInfoUi(form);
  }

  /** 저장 직: 영업정보 인코딩 + 업체전화·이메일·영업정보 필수 검사. 실패 시 false */
  function pgPrepareSalesInfoAndContactRequired(form, fd) {
    if (!form || !fd) return true;
    var hasSalesUi = !!form.querySelector('[data-sales-info-wrap]');
    if (hasSalesUi) {
      var type = String(fd.salesInfoType != null ? fd.salesInfoType : '').trim().toUpperCase();
      var detail = String(fd.addrEtc != null ? fd.addrEtc : '').trim();
      if (!type) {
        alert(pgAdminUiT('영업정보 / 기타를 선택하세요.'));
        return false;
      }
      if ((type === 'ONLINE' || type === 'OFFLINE') && !detail) {
        alert(type === 'ONLINE'
          ? pgAdminUiT('온라인은 도메인을 입력하세요.')
          : pgAdminUiT('오프라인은 상호명을 입력하세요.'));
        return false;
      }
      fd.addrEtc = pgEncodeSalesInfoAddrEtc(type, detail);
      delete fd.salesInfoType;
    }
    var emailEl = form.querySelector('[name="email"]');
    var emailRequired = !!(emailEl && (
      emailEl.classList.contains('required-input') ||
      (emailEl.closest('.form-field-block') && emailEl.closest('.form-field-block').querySelector('.text-danger'))
    ));
    if (emailRequired || hasSalesUi) {
      var email = String(fd.email != null ? fd.email : '').trim();
      if (!email) {
        alert(pgAdminUiT('이메일을 입력하세요.'));
        return false;
      }
      if (email.indexOf('@') < 0) {
        alert(pgAdminUiT('올바른 이메일 형식을 입력하세요.'));
        return false;
      }
    }
    var telEl = form.querySelector('[name="compTel"]');
    var telRequired = !!(telEl && (
      telEl.classList.contains('required-input') ||
      (telEl.closest('.form-field-block') && telEl.closest('.form-field-block').querySelector('.text-danger'))
    ));
    if (telRequired || hasSalesUi) {
      var tel = String(fd.compTel != null ? fd.compTel : '').trim();
      var numOnly = tel.replace(/[^0-9]/g, '');
      if (!tel || numOnly.length < 4) {
        alert(pgAdminUiT('업체전화를 입력하세요.'));
        return false;
      }
    }
    return true;
  }

  /** 가맹 모바일 결제창 — EMBED | MOBILE_REDIRECT | ALWAYS_REDIRECT (빈값=본사 기본) */
  function pgNormalizeMobileCheckoutModeValue(raw) {
    if (raw == null) return '';
    var v = String(raw).trim().toUpperCase();
    if (!v) return '';
    if (v === 'MOBILE' || v === 'MOBILE_REDIRECT') return 'MOBILE_REDIRECT';
    if (v === 'REDIRECT' || v === 'ALWAYS' || v === 'ALWAYS_REDIRECT') return 'ALWAYS_REDIRECT';
    if (v === 'EMBED') return 'EMBED';
    return '';
  }

  function pgApplyMobileCheckoutModeField(root, raw) {
    if (!root || !root.querySelector) return;
    var el = root.querySelector('[name="mobileCheckoutMode"]');
    if (!el) return;
    el.value = pgNormalizeMobileCheckoutModeValue(raw);
  }

  /** 업체 폼 저장 시 숨김 카드(.d-none·display:none·allowlist) 제외, 동일 name 은 비어 있지 않은 값 우선 */
  function pgIsCompFormCardHiddenForSave(card) {
    if (!card) return false;
    if (card.classList.contains('d-none')) return true;
    if (card.getAttribute('data-pg-merchant-allowlist-hidden') === 'Y') return true;
    if (card.style && card.style.display === 'none') return true;
    return false;
  }

  function pgIsCompFormFieldSkippedForSave(el) {
    if (!el || !el.name || el.type === 'file' || el.name === 'pgOperational') return true;
    if (el.name.indexOf('__phone_') === 0) return true;
    var card = el.closest('.card');
    if (pgIsCompFormCardHiddenForSave(card)) return true;
    /* 상호명: 본사·총판 전용 — 숨김이면 이전 업체 잔존값 저장 방지 */
    if (el.name === 'tradeNm') {
      var tnBlock = el.closest('.trade-nm-regional-master-only');
      if (tnBlock && tnBlock.classList.contains('d-none')) return true;
    }
    return false;
  }

  /** 가맹 웹결제 카드 — 저장 시 노출 중인 #webPaymentCard 값을 fd에 반영(FOLLOW_HQ 등 누락 방지) */
  function pgMergeMerchantUrlPaySaveFields(form, fd, compDivVal) {
    if (!form || !fd || String(compDivVal || '').toUpperCase() !== 'MERCHANT') return fd;
    var card = form.querySelector('#webPaymentCard');
    if (!card || pgIsCompFormCardHiddenForSave(card)) return fd;
    ['urlPayInputMode', 'urlPayCardExpiryMode', 'webPaymentUseYn', 'urlPayCheckoutMode',
      'urlPayProductNameUseYn', 'urlPayCompanyNameShowYn', 'urlPayLangMenuUseYn', 'checkoutContactRememberMode', 'urlPayShippingAddressUseYn',
      'urlPayBuyerEmailUseYn', 'urlPayBuyerCountryUseYn', 'urlPayBuyerPhoneUseYn',
      'urlPayCheckoutFieldPresetId',
      'checkoutContactRememberMode'
    ].forEach(function (n) {
      var el = card.querySelector('[name="' + n + '"]');
      if (el && el.name) fd[n] = el.value;
    });
    return fd;
  }

  /** 가맹 결제통보 URL — 조회 시 항상 초기화 후 반영(이전 가맹 값 잔류 방지) */
  function pgApplyMerchantNotifyUrlFieldsFromDetail(form, data) {
    if (!form) return;
    ['notifyUrlBackground', 'notifyUrlResult', 'jpayNotifyUrl', 'jpayCallbackUrl'].forEach(function (k) {
      var v = data && data[k] != null ? String(data[k]) : '';
      form.querySelectorAll('[name="' + k + '"]').forEach(function (el) {
        if (el.type === 'file') return;
        el.value = v;
        if (k === 'jpayNotifyUrl' || k === 'jpayCallbackUrl') {
          el.removeAttribute('data-pg-plain-url');
          el.removeAttribute('data-pg-jpay-url-masked');
          if (v) el.setAttribute('data-pg-plain-url', v);
        }
      });
    });
  }

  /** 저장 시 노출 중인 결제통보 URL 카드 값만 반영(숨김·중복 name 잔류값 제외) */
  function pgMergeMerchantNotifyUrlSaveFields(form, fd, compDivVal) {
    if (!form || !fd) return fd;
    if (String(compDivVal || '').toUpperCase() !== 'MERCHANT') return fd;
    var notifyCard = form.querySelector('#notifyUrlCard');
    if (notifyCard && !pgIsCompFormCardHiddenForSave(notifyCard)) {
      ['notifyUrlBackground', 'notifyUrlResult'].forEach(function (n) {
        var el = notifyCard.querySelector('[name="' + n + '"]');
        fd[n] = el ? String(el.value || '').trim() : '';
      });
    } else {
      fd.notifyUrlBackground = '';
      fd.notifyUrlResult = '';
    }
    var jpayCard = form.querySelector('#jpayNotifyUrlCard');
    if (jpayCard && !pgIsCompFormCardHiddenForSave(jpayCard)) {
      ['jpayNotifyUrl', 'jpayCallbackUrl'].forEach(function (n) {
        var el = jpayCard.querySelector('[name="' + n + '"]');
        if (!el) return;
        var plain = (el.getAttribute('data-pg-plain-url') || el.value || '').trim();
        fd[n] = plain;
      });
    } else {
      // 카드 미노출(권한) 시 폼 잔여 빈값으로 기존 JPAY URL을 지우지 않음(서버 null=유지)
      delete fd.jpayNotifyUrl;
      delete fd.jpayCallbackUrl;
    }
    return fd;
  }

  function pgApplyUrlPayInputModeSelectFromDetail(form, rawMode) {
    if (!form) return;
    var uim = form.querySelector('#merchantCheckoutCompositionCard [name="urlPayInputMode"]')
      || form.querySelector('#webPaymentCard [name="urlPayInputMode"]');
    if (!uim) return;
    var im = String(rawMode != null ? rawMode : 'GENERAL').trim().toUpperCase();
    var validInputModes = (window.PG_URL_PAY_INPUT_MODE && PG_URL_PAY_INPUT_MODE.ALL_MODES)
      ? PG_URL_PAY_INPUT_MODE.ALL_MODES.slice()
      : ['FOLLOW_HQ', 'GENERAL', 'TYPE_AA', 'TYPE_BA', 'TYPE_AN', 'TYPE_AG', 'TYPE_AF', 'TYPE_AE',
        'TYPE_BN', 'TYPE_BG', 'TYPE_BF', 'TYPE_BE', 'TYPE_CN'];
    if (validInputModes.indexOf(im) < 0 && window.PG_URL_PAY_INPUT_MODE && PG_URL_PAY_INPUT_MODE.normalize) {
      im = PG_URL_PAY_INPUT_MODE.normalize(im);
    } else if (validInputModes.indexOf(im) < 0 && window.PG_URL_PAY_SHELL && PG_URL_PAY_SHELL.normalizeUrlPayInputMode) {
      im = PG_URL_PAY_SHELL.normalizeUrlPayInputMode(im);
    }
    if (validInputModes.indexOf(im) < 0) im = 'GENERAL';
    uim.value = im;
    var cardSync = form.querySelector('#webPaymentCard');
    if (cardSync) pgSyncUrlPayInputModeHint(cardSync, im);
  }

  function pgApplyUrlPayCardExpiryModeSelectFromDetail(form, rawMode) {
    if (!form) return;
    var el = form.querySelector('#webPaymentCard [name="urlPayCardExpiryMode"]');
    if (!el) return;
    var im = String(rawMode != null ? rawMode : 'FOLLOW_HQ').trim().toUpperCase();
    var valid = ['FOLLOW_HQ', 'DROPDOWN', 'TEXT', 'HYBRID', 'AI_B', 'AI_A'];
    if (valid.indexOf(im) < 0 && window.PG_JPAY_CARD_EXPIRY && PG_JPAY_CARD_EXPIRY.normalizeMode) {
      im = PG_JPAY_CARD_EXPIRY.normalizeMode(im);
    }
    if (valid.indexOf(im) < 0) im = 'FOLLOW_HQ';
    el.value = im;
  }

  function pgCollectCompFormFields(form) {
    var fd = {};
    if (!form) return fd;
    var splitCard = form.querySelector('#splitPayCard');
    if (splitCard) pgSyncSplitPayHiddenFields(splitCard);
    form.querySelectorAll('input, select, textarea').forEach(function (el) {
      if (pgIsCompFormFieldSkippedForSave(el)) return;
      var val = el.value;
      if (Object.prototype.hasOwnProperty.call(fd, el.name)) {
        var prev = String(fd[el.name] || '').trim();
        var cur = String(val || '').trim();
        if (prev !== '' && cur === '') return;
      }
      fd[el.name] = val;
    });
    return fd;
  }

  /** 조회 후 비고 — 초기화·중복 필드 처리 뒤 기본정보 비고란까지 동기화 */
  function pgFinalizeCompRemarkFill(form, data) {
    if (!form || !data || !Object.prototype.hasOwnProperty.call(data, 'remark')) return;
    pgSetCompFormFieldValues(form, 'remark', data.remark != null ? data.remark : '');
  }

  /** 국가·은행·주소 국가 — country-bank-row / country-address-row 가 여러 개일 때 일괄 반영 */
  function pgApplyCompDetailCountryBankFill(pane, form, data) {
    if (!form || !data) return;
    var cc = data.countryCd;
    if (cc && cc !== 'JP' && cc !== 'KR' && cc !== 'TH') {
      form.querySelectorAll('select[name="countryCd"]').forEach(function (countrySel) {
        countrySel.value = 'OTHER';
        countrySel.dispatchEvent(new Event('change'));
        var row = countrySel.closest('.country-bank-row');
        var countryOther = row ? row.querySelector('[name="countryCdOther"]') : null;
        var bankText = row ? row.querySelector('input[name="bankCdText"]') : null;
        if (countryOther) countryOther.value = cc;
        if (bankText && data.bankCd != null) bankText.value = data.bankCd;
      });
    } else if (cc === 'JP' || cc === 'KR' || cc === 'TH') {
      form.querySelectorAll('select[name="countryCd"]').forEach(function (countrySel) {
        countrySel.value = cc;
      });
      refreshCountryBankAfterFill(pane, data.bankCd);
    }
    var acc = data.addrCountryCd;
    if (acc && acc !== 'JP' && acc !== 'KR' && acc !== 'TH') {
      form.querySelectorAll('select[name="addrCountryCd"]').forEach(function (addrCountrySel) {
        addrCountrySel.value = 'OTHER';
        addrCountrySel.dispatchEvent(new Event('change'));
        var addrRow = addrCountrySel.closest('.country-address-row');
        var addrCountryOther = addrRow ? addrRow.querySelector('[name="addrCountryCdOther"]') : null;
        if (addrCountryOther) addrCountryOther.value = acc;
      });
    } else if (acc === 'JP' || acc === 'KR' || acc === 'TH') {
      form.querySelectorAll('select[name="addrCountryCd"]').forEach(function (addrCountrySel) {
        addrCountrySel.value = acc;
      });
    }
  }

  /** 업체 상세 등: 수수료·보류 관련 숫자 필드만 동일 표기 규칙 적용. 해당 없으면 null. */
  function pgFmtCompDetailNumericField(fieldName, v) {
    var pctFields = { payRate: 1, feeUsdt: 1, feeFx: 1, rollingPct: 1, holdRate: 1 };
    var amtFields = { failFee: 1, usageRate: 1, cancelRate: 1, voidFeePerTx: 1, manualVoidFeePerTx: 1, refundRate: 1, feeSettlementPerTx: 1, remittanceTransferFee: 1, usdtTransferFeeUsd: 1, chargebackFeePerTx: 1, perTxFee: 1 };
    var dayFields = { rollingDays: 1, holdDays: 1 };
    if (pctFields[fieldName]) return pgFmtPctOneDecimalInput(v);
    if (amtFields[fieldName]) return pgFmtOneDecimalStripWhole(v);
    if (dayFields[fieldName]) {
      var n = parseFloat(String(v).replace(/,/g, '.'));
      return isFinite(n) ? String(Math.round(n)) : String(v);
    }
    return null;
  }

  /** 본사 수수료 템플릿: 배포(Y)만. 기준통화가 있으면 정책 통화와 일치하거나 정책 통화가 비어 있으면(레거시) 전체 허용 */
  function pgFilterDeployedTemplatesForMerchant(templates, baseCurrency) {
    var bc = (baseCurrency || '').trim().toUpperCase();
    var out = [];
    (templates || []).forEach(function (t) {
      if (String(t.deployYn || '').toUpperCase() !== 'Y') return;
      var tc = (t.currencyCode != null && String(t.currencyCode).trim() !== '') ? String(t.currencyCode).trim().toUpperCase() : '';
      if (bc && tc && tc !== bc) return;
      out.push(t);
    });
    return out;
  }
  /** 필터 결과에 없는데 DB에 저장된 scope가 있으면 전체 템플릿에서 찾아 옵션에 포함(미배포·통화 필터 제외 등). 없으면 scope 코드만 표시. */
  function pgAugmentFilteredHqTemplates(filt, allTemplates, savedScope) {
    var s = savedScope != null ? String(savedScope).trim() : '';
    if (!s) return filt || [];
    var arr = (filt || []).slice();
    var found = false;
    var i;
    for (i = 0; i < arr.length; i++) {
      if (String(arr[i].scope || '').trim() === s) {
        found = true;
        break;
      }
    }
    if (found) return arr;
    var full = (allTemplates || []).filter(function (t) {
      return String(t.scope || '').trim() === s;
    });
    if (full.length) {
      arr.push(full[0]);
      return arr;
    }
    arr.push({ scope: s, policyName: s + ' (저장된 정책·목록에 없음)', deployYn: 'N', currencyCode: '' });
    return arr;
  }
  function pgHqPolicyScopeOptionsHtml(filteredTemplates) {
    var opts = '<option value="">본사 기본 템플릿 (DEFAULT)</option>';
    (filteredTemplates || []).forEach(function (t) {
      var scope = t.scope || '';
      var name = t.policyName || scope;
      var cc = (t.currencyCode != null && String(t.currencyCode).trim() !== '') ? String(t.currencyCode).trim().toUpperCase() : '';
      var lab = name + (cc ? ' (' + cc + ')' : '');
      opts += '<option value="' + String(scope).replace(/"/g, '&quot;') + '">' +
        String(lab).replace(/</g, '&lt;').replace(/"/g, '&quot;') + '</option>';
    });
    return opts;
  }

  function pgToggleUsdDependentCommissionFields(rootEl, baseCurrency) {
    if (!rootEl) return;
    var isUsd = String(baseCurrency || '').trim().toUpperCase() === 'USD';
    ['usdtTransferFeeUsd', 'feeUsdt'].forEach(function (name) {
      var el = rootEl.querySelector('[name="' + name + '"]');
      if (!el) return;
      if (isUsd) {
        el.disabled = false;
      } else {
        el.disabled = true;
        el.value = '';
      }
    });
  }

