  window.PG_MENU_INFO = MENU_INFO;

  var config = window.SITE_CONFIG;
  var TAB_UL = 'copyTopTabUl';
  var TAB_MAIN = 'topTapMain';
  var CONTENT_FRAME = 'content-frame';
  var PLACEHOLDER_ID = 'content-placeholder';
  var TABLE_ROW_PADDING_KEY = 'pg_table_row_padding_y';

  function getTableRowPaddingY() {
    var v = parseInt(localStorage.getItem(TABLE_ROW_PADDING_KEY), 10);
    return (isNaN(v) || v < 4 || v > 40) ? 6 : v;
  }
  function setTableRowPaddingY(px) {
    var v = Math.max(4, Math.min(40, px));
    document.documentElement.style.setProperty('--table-row-padding-y', v + 'px');
    localStorage.setItem(TABLE_ROW_PADDING_KEY, String(v));
  }
  /** 예전: 행 사이 점선 리사이즈 줄 삽입. UX상 제거(그리드·목록 테이블 공통). */
  function injectTableRowResizeHandles(/* tbody, colCount */) {
    return;
  }

  function getTabIdFromUrl(url) {
    if (!url || url === '/main') return 'main';
    var pathOnly = String(url || '').split('?')[0];
    var path = pathOnly.replace(/^\//, '').replace(/\//g, '_');
    return path || 'main';
  }

  function pgResolveNavUrlFull(url) {
    var layoutB = window.PG_MENU_LAYOUT_B;
    if (layoutB && layoutB.enabled && typeof layoutB.resolveNavUrl === 'function') {
      return layoutB.resolveNavUrl(url) || url;
    }
    return url;
  }

  function pgNormalizeTopTabUrl(url) {
    var u = pgResolveNavUrlFull(url);
    if (!u || u === '/main') return u;
    var path = String(u).split('?')[0];
    var layoutB = window.PG_MENU_LAYOUT_B;
    if (layoutB && layoutB.enabled && layoutB.isHubUrl && layoutB.isHubUrl(path)) return path;
    return u;
  }

  function pgIsHubUrlPath(url) {
    var path = String(url || '').split('?')[0];
    var layoutB = window.PG_MENU_LAYOUT_B;
    return !!(layoutB && layoutB.enabled && layoutB.isHubUrl && layoutB.isHubUrl(path));
  }

  function pgHubMenuAllowed(hubPath) {
    var layoutB = window.PG_MENU_LAYOUT_B;
    if (!layoutB || !layoutB.enabled || !layoutB.leafUrlsForHub) return false;
    var leaves = layoutB.leafUrlsForHub(hubPath) || [];
    for (var i = 0; i < leaves.length; i++) {
      var leaf = leaves[i];
      if (leaf === '/set/gridSetMng') {
        if (getPagePermissionForUrl(leaf) !== 'NONE') return true;
        continue;
      }
      if (getPagePermissionForUrl(leaf) === 'NONE') continue;
      if (isMerchantChatbotMenuForbidden(leaf)) continue;
      if (isMerchantChatbotPayHistoryMenuForbidden(leaf)) continue;
      if (isMerchantSplitPayMenuForbidden(leaf)) continue;
      if (isMerchantJpaySubscriptionMenuForbidden(leaf)) continue;
      if (isMerchantApiPortalMenuForbidden(leaf)) continue;
      return true;
    }
    return false;
  }

  function getSessionUser() {
    try { return JSON.parse(sessionStorage.getItem('pg_admin_user') || '{}') || {}; } catch (e) { return {}; }
  }

  /** 총본사·본사·총판 로그인만 가맹점 운영기록 카드 열람·저장 */
  function pgViewerCanManageMerchantOpsRecord() {
    var u = getSessionUser();
    if (String((u && u.role) || '').toUpperCase() === 'ADMIN') return true;
    var ol = String((u && u.orgLevel) || '').toUpperCase();
    return ol === 'HEADQUARTERS' || ol === 'REGIONAL' || ol === 'MASTER_DIST';
  }

  function pgApplyMerchantOpsRecordCardVisibility(pane, isMerchant) {
    if (!pane) return;
    var show = !!isMerchant && pgViewerCanManageMerchantOpsRecord();
    pane.querySelectorAll('.merchant-ops-record-section').forEach(function (card) {
      if (show) card.classList.remove('d-none'); else card.classList.add('d-none');
    });
  }

  // 업체관리는 내 조직 기준 하위만 노출(상위 조직 미노출). 편집 가능 여부는 권한(OBSERVER/MODIFY/DELETE)로 별도 제어.
  // API가 본인 행을 빼고 하위만 줄 때도(영업점 등) orgUnitId로 하위만 남긴다. me 없을 때 전체 목록을 그대로 두지 않는다.
  function applyObserverCompTreeScope(list, url) {
    if (url !== '/comp/compMngTree') return list || [];
    if (!Array.isArray(list) || list.length === 0) return list || [];
    var u = getSessionUser();
    if (u && String(u.role || '').toUpperCase() === 'ADMIN') return list;

    var myCompId = String((u && u.compId) || '').trim();
    var myOuId = u && u.orgUnitId != null && u.orgUnitId !== '' ? String(u.orgUnitId) : '';
    if (!myCompId && !myOuId) return list;

    var byCompId = {};
    list.forEach(function (r) {
      if (!r) return;
      var cid = r.compId != null ? String(r.compId).trim() : '';
      if (cid) byCompId[cid] = r;
    });
    var me = myCompId ? byCompId[myCompId] : null;

    var keepIds = {};
    var seedParents = [];

    if (me && me.id != null) {
      var myId = String(me.id);
      keepIds[myId] = true;
      seedParents.push(myId);
    } else if (myOuId) {
      seedParents.push(myOuId);
    } else {
      return [];
    }

    seedParents.forEach(function (rootParent) {
      var q = [rootParent];
      var qi = 0;
      while (qi < q.length) {
        var parent = q[qi++];
        list.forEach(function (r) {
          var rid = r && r.id != null ? String(r.id) : '';
          var rpid = r && r.parentId != null ? String(r.parentId) : '';
          if (!rid || !rpid) return;
          if (rpid === parent && !keepIds[rid]) {
            keepIds[rid] = true;
            q.push(rid);
          }
        });
      }
    });

    if (Object.keys(keepIds).length === 0) return [];
    return list.filter(function (r) {
      var rid = r && r.id != null ? String(r.id) : '';
      return !!keepIds[rid];
    });
  }

  /** 업체관리 상세: 본인 소속 업체(compId) 레코드는 조회만(저장 버튼 비활성). API도 READ_ONLY_SELF_COMP. */
  window.applyCompDetailReadOnlyIfOwnNonMerchant = function (pane) {
    if (!pane) return;
    pane.classList.remove('pg-comp-detail-self-readonly');
    var form = pane.querySelector('#compDetailForm');
    if (!form) return;
    var u = getSessionUser();
    if (u && String(u.role || '').toUpperCase() === 'ADMIN') return;
    var mine = String((u && u.compId) || '').trim();
    var cidEl = form.querySelector('[name="compId"]');
    var cid = cidEl && cidEl.value ? String(cidEl.value).trim() : '';
    if (!mine || !cid || mine !== cid) return;
    pane.classList.add('pg-comp-detail-self-readonly');
    form.querySelectorAll('input, select, textarea').forEach(function (el) {
      if (el.type === 'hidden') return;
      el.disabled = true;
      if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') el.readOnly = true;
    });
    var saveBtn = pane.querySelector('#compDetailSaveBtn');
    if (saveBtn) {
      saveBtn.disabled = true;
      saveBtn.setAttribute('aria-disabled', 'true');
      saveBtn.classList.remove('btn-primary', 'btn-success', 'btn-danger', 'btn-info', 'btn-warning');
      saveBtn.classList.add('btn-secondary');
      saveBtn.style.pointerEvents = 'none';
    }
  };

  /** 백엔드 {@code ChatbotMerchantAdminConstants.PERMISSION_GROUP_NM} 및 구 명칭 */
  var PG_CHATBOT_MERCHANT_GROUP_NM = 'CHATBOT';
  var PG_CHATBOT_MERCHANT_GROUP_LEGACY = '챗봇관리자';

  function merchantChatbotPaymentEnabledInSession() {
    var s = getSessionUser();
    return s && String(s.chatbotPaymentUseYn || 'N').trim().toUpperCase() === 'Y';
  }

  function merchantSplitPayEnabledInSession() {
    var s = getSessionUser();
    return s && String(s.splitPayEnabledYn || 'N').trim().toUpperCase() === 'Y';
  }

  function merchantJpaySubscriptionEnabledInSession() {
    var s = getSessionUser();
    return s && String(s.apiJpaySubscriptionUseYn || 'N').trim().toUpperCase() === 'Y';
  }

  var PG_SPLIT_PAY_MENU_URLS = [
    '/calc/splitPayList',
    '/pay/splitPay',
    '/splitpay/progressMng',
    '/splitpay/mailMng'
  ];

  function isSplitPayMenuUrl(url) {
    return PG_SPLIT_PAY_MENU_URLS.indexOf(url || '') >= 0;
  }

  /** 관리자 웹(icopay): 업체 대표 또는 CHATBOT 권한그룹(구 챗봇관리자)만 챗봇 메뉴 허용 — 보조(ASSISTANT)는 CHATBOT만 */
  function merchantIcopayMayAccessChatbotMenus(sess) {
    if (!sess) return false;
    var ut = String(sess.userType || '').trim().toUpperCase();
    if (ut !== 'ASSISTANT') return true;
    var pgn = String(sess.permissionGroupNm || '').trim();
    return pgn === PG_CHATBOT_MERCHANT_GROUP_NM || pgn === PG_CHATBOT_MERCHANT_GROUP_LEGACY;
  }

  /**
   * 가맹·챗봇결제 사용(Y)인데 대표·CHATBOT 계정이 아닌 경우 — 조직 권한맵이 넓어도 상품/기본설정 메뉴·화면 차단.
   */
  function shouldForceNoneMerchantChatbotProductUrls(url) {
    if (url !== '/chatbot/productMng' && url !== '/chatbot/chatbotKbMng' && url !== '/chatbot/orderMng') return false;
    var sess = getSessionUser();
    if (!sess || String(sess.role || '').toUpperCase() === 'ADMIN') return false;
    if (String(sess.orgLevel || '').toUpperCase() !== 'MERCHANT') return false;
    if (!merchantChatbotPaymentEnabledInSession()) return false;
    return !merchantIcopayMayAccessChatbotMenus(sess);
  }

  /**
   * 조직별 권한 세팅(pagePermissions)만 사용 — 가맹점 전용 하드코딩 제거.
   * NONE / OBSERVER / MODIFY / DELETE. 조직 연결 계정은 pagePermissions 적용(ADMIN 포함).
   * 조직 미연결 ADMIN·pagePermissions 없음 → DELETE(무제한).
   */
  function getPagePermissionForUrl(url) {
    if (!url || url === '/main') return 'DELETE';
    var urlPath = String(url).split('?')[0];
    var u = getSessionUser();
    /* 허브 URL: leaf 중 하나라도 허용이면 메뉴 접근 가능(탭별 권한은 허브 shell에서 필터) */
    if (pgIsHubUrlPath(urlPath)) {
      var ppHub = u && u.pagePermissions;
      if (ppHub && typeof ppHub === 'object') {
        return pgHubMenuAllowed(urlPath) ? 'DELETE' : 'NONE';
      }
      if (u && String(u.role || '').toUpperCase() === 'ADMIN') return 'DELETE';
      return 'DELETE';
    }
    var pp = u && u.pagePermissions;
    if (pp && typeof pp === 'object') {
      var aliases = [urlPath];
      if (url !== urlPath && aliases.indexOf(url) < 0) aliases.push(url);
      if (window.PG_MENU_LAYOUT_B && window.PG_MENU_LAYOUT_B.enabled && typeof window.PG_MENU_LAYOUT_B.permissionAliases === 'function') {
        window.PG_MENU_LAYOUT_B.permissionAliases(urlPath).forEach(function (a) {
          /* 허브 URL 권한은 leaf별 권한과 섞지 않음(형제 탭 권한 누수 방지) */
          if (a && aliases.indexOf(a) < 0 && !pgIsHubUrlPath(a)) aliases.push(a);
        });
      }
      /* 구 연동키트 URL ↔ 키·문서 동일 화면만 (형제 탭·공통설정과 권한 공유 금지) */
      if (urlPath === '/hq/merchantApiDeployKit' || urlPath === '/hq/merchantApiGenerate') {
        aliases.push('/hq/merchantApiDeployKit');
        aliases.push('/hq/merchantApiGenerate');
      }
      // 업체정보조회 권한은 compInfo/myCompMng 중 어느 키로 저장돼도 동일 적용
      if (url === '/comp/myCompMng') aliases.push('/comp/compInfo');
      else if (url === '/comp/compInfo') aliases.push('/comp/myCompMng');
      // 정산: /settlement/unpaidMng 는 메뉴·권한 카탈로그의 /calc/unpaidMng 와 동일
      if (url === '/settlement/unpaidMng') aliases.push('/calc/unpaidMng');
      else if (url === '/calc/unpaidMng') aliases.push('/settlement/unpaidMng');
      // 업체상세(compDetail)는 업체관리(compMngTree) 권한을 따라간다.
      if (url === '/comp/compDetail') aliases.push('/comp/compMngTree');
      else if (url === '/comp/compMngTree') aliases.push('/comp/compDetail');
      // 챗봇관리 — 기본설정·상품관리·주문관리: 동일 메뉴 권한
      if (url === '/chatbot/productMng' || url === '/chatbot/chatbotKbMng' || url === '/chatbot/orderMng') {
        aliases.push('/chatbot/productMng');
        aliases.push('/chatbot/chatbotKbMng');
        aliases.push('/chatbot/orderMng');
      }
      if (isSplitPayMenuUrl(url)) {
        PG_SPLIT_PAY_MENU_URLS.forEach(function (spu) { if (aliases.indexOf(spu) < 0) aliases.push(spu); });
      }
      // 배포 문서 — 구 운영관리(/ops/*) ↔ 배포설정(/deploy/*) 동일 화면 rename만 (형제 문서와 권한 공유 금지)
      if (urlPath === '/deploy/launchGuide' || urlPath === '/ops/launchGuide') {
        aliases.push('/deploy/launchGuide');
        aliases.push('/ops/launchGuide');
      } else if (urlPath === '/deploy/integrationPlan' || urlPath === '/ops/integrationPlan') {
        aliases.push('/deploy/integrationPlan');
        aliases.push('/ops/integrationPlan');
      } else if (urlPath === '/deploy/jpayWorkPlan' || urlPath === '/ops/jpayWorkPlan') {
        aliases.push('/deploy/jpayWorkPlan');
        aliases.push('/ops/jpayWorkPlan');
      } else if (urlPath === '/deploy/merchantApiPolicy' || urlPath === '/ops/merchantApiPolicy') {
        aliases.push('/deploy/merchantApiPolicy');
        aliases.push('/ops/merchantApiPolicy');
      } else if (urlPath === '/deploy/launchChecklist' || urlPath === '/ops/launchChecklist') {
        aliases.push('/deploy/launchChecklist');
        aliases.push('/ops/launchChecklist');
      }
      for (var i = 0; i < aliases.length; i++) {
        var key = aliases[i];
        if (Object.prototype.hasOwnProperty.call(pp, key)) {
          var pv = pp[key];
          var perm = pv != null && String(pv).trim() !== '' ? String(pv).trim().toUpperCase() : 'DELETE';
          if (shouldForceNoneMerchantChatbotProductUrls(url) && perm !== 'NONE') return 'NONE';
          return perm;
        }
      }
      /* 조직 권한맵이 있으면 미등재 URL은 접근불가(기본 허용 금지) */
      if (shouldForceNoneMerchantChatbotProductUrls(url)) return 'NONE';
      return 'NONE';
    }
    if (u && String(u.role || '').toUpperCase() === 'ADMIN') return 'DELETE';
    var permFb = 'DELETE';
    if (shouldForceNoneMerchantChatbotProductUrls(url) && permFb !== 'NONE') return 'NONE';
    return permFb;
  }

  /** OBSERVER_HELLO→OBSERVER, MODIFY_HELLO→MODIFY — 쓰기·삭제 판단용 */
  function pagePermBase(perm) {
    var p = (perm != null ? String(perm) : 'DELETE').trim().toUpperCase();
    if (p === 'OBSERVER_HELLO') return 'OBSERVER';
    if (p === 'MODIFY_HELLO') return 'MODIFY';
    return p;
  }
  /** DELETE·OBSERVER_HELLO·MODIFY_HELLO 만 헬로(안내·VIEW SETTING 토글) 허용 */
  function pagePermHelloAllowed(perm) {
    var p = (perm != null ? String(perm) : '').trim().toUpperCase();
    return p === 'DELETE' || p === 'OBSERVER_HELLO' || p === 'MODIFY_HELLO';
  }
  function pagePermCanWrite(perm) {
    var b = pagePermBase(perm);
    return b === 'MODIFY' || b === 'DELETE';
  }
  function pagePermIsObserver(perm) {
    return pagePermBase(perm) === 'OBSERVER';
  }
  try {
    window.pagePermBase = pagePermBase;
    window.pagePermHelloAllowed = pagePermHelloAllowed;
    window.pagePermCanWrite = pagePermCanWrite;
    window.pagePermIsObserver = pagePermIsObserver;
  } catch (ePermEx) { /* ignore */ }

  /** 가맹점(MERCHANT) & 웹결제(Y)+브로커 시크릿(발행·재발행) 미충족 시 merchantApiDeployedYn=N — ADMIN은 예외 */
  function merchantApiDeployedInSession() {
    var s = getSessionUser();
    if (!s || String(s.merchantApiDeployedYn || 'N').trim().toUpperCase() !== 'Y') return false;
    if (String(s.orgLevel || '').toUpperCase() === 'MERCHANT'
        && String(s.webPaymentUseYn || 'N').trim().toUpperCase() !== 'Y') {
      return false;
    }
    return true;
  }

  /** 가맹점API — 미충족 시 사이드바 메뉴 항목 자체를 숨김(display:none). 회색 비활성이 아님. */
  function isMerchantApiPortalMenuForbidden(url) {
    if (url !== '/comp/merchantApiPortal') return false;
    var sess = getSessionUser();
    if (!sess || String(sess.role || '').toUpperCase() === 'ADMIN') return false;
    if (String(sess.orgLevel || '').toUpperCase() !== 'MERCHANT') return true;
    return !merchantApiDeployedInSession();
  }

  function isMerchantChatbotMenuForbidden(url) {
    var u = url || '';
    if (u !== '/chatbot/productMng' && u !== '/chatbot/chatbotKbMng' && u !== '/chatbot/orderMng') return false;
    var sess = getSessionUser();
    if (!sess || String(sess.role || '').toUpperCase() === 'ADMIN') return false;
    var ol = String(sess.orgLevel != null ? sess.orgLevel : '').toUpperCase();
    if (ol !== 'MERCHANT') return false;
    return String(sess.chatbotPaymentUseYn || 'N').trim().toUpperCase() !== 'Y';
  }

  /** 가맹점(MERCHANT) & 챗봇결제 미사용 시 챗봇결제내역 메뉴 숨김 */
  function isMerchantChatbotPayHistoryMenuForbidden(url) {
    if (url !== '/pay/chatbotPay') return false;
    var sess = getSessionUser();
    if (!sess || String(sess.role || '').toUpperCase() === 'ADMIN') return false;
    if (String(sess.orgLevel || '').toUpperCase() !== 'MERCHANT') return false;
    return String(sess.chatbotPaymentUseYn || 'N').trim().toUpperCase() !== 'Y';
  }

  /** 가맹점(MERCHANT) & 분할결제 미사용 시 분할관리·분할결제 메뉴 숨김 */
  function isMerchantSplitPayMenuForbidden(url) {
    if (!isSplitPayMenuUrl(url)) return false;
    var sess = getSessionUser();
    if (!sess || String(sess.role || '').toUpperCase() === 'ADMIN') return false;
    if (String(sess.orgLevel || '').toUpperCase() !== 'MERCHANT') return false;
    return String(sess.splitPayEnabledYn || 'N').trim().toUpperCase() !== 'Y';
  }

  /** 가맹점(MERCHANT) & JPAY API 구독결제 미사용 시 구독결제내역 메뉴 숨김 */
  function isMerchantJpaySubscriptionMenuForbidden(url) {
    if (url !== '/pay/jpaySubscription') return false;
    var sess = getSessionUser();
    if (!sess || String(sess.role || '').toUpperCase() === 'ADMIN') return false;
    if (String(sess.orgLevel || '').toUpperCase() !== 'MERCHANT') return false;
    return String(sess.apiJpaySubscriptionUseYn || 'N').trim().toUpperCase() !== 'Y';
  }

  function isHeadquartersSessionUser() {
    var u = getSessionUser();
    if (!u) return false;
    if (String(u.role || '').toUpperCase() === 'ADMIN') return true;
    return String(u.orgLevel != null ? u.orgLevel : '').toUpperCase() === 'HEADQUARTERS';
  }

  function isMenuAllowedForCurrentUser(url) {
    var urlPath = String(url || '').split('?')[0];
    if (pgIsHubUrlPath(urlPath)) return pgHubMenuAllowed(urlPath);
    if (urlPath === '/hq/businessDaySetting' && !isHeadquartersSessionUser()) return false;
    if (urlPath === '/hq/notifyEpMirror' && !isHeadquartersSessionUser()) return false;
    if (urlPath === '/splitpay/emailSettings' && !isHeadquartersSessionUser()) return false;
    if (getPagePermissionForUrl(urlPath) === 'NONE') return false;
    if (isMerchantChatbotMenuForbidden(url)) return false;
    if (isMerchantChatbotPayHistoryMenuForbidden(url)) return false;
    if (isMerchantSplitPayMenuForbidden(url)) return false;
    if (isMerchantJpaySubscriptionMenuForbidden(url)) return false;
    if (isMerchantApiPortalMenuForbidden(url)) return false;
    return true;
  }

  /** SUPERVISOR만 실행 가능한 메뉴(조직 상한 DELETE여도 일반 총판 사용자는 불가) */
  function pgIsSupervisorOnlyMenuUrl(url) {
    var path = String(url || '').split('?')[0];
    return path === '/ops/notiProvision';
  }

  /** 본사권한·사용자 매트릭스 공통 권한 라벨 (SUPERVISOR 전용 메뉴는 별도 표기) */
  function pgPermCodeLabel(code, pageUrl) {
    var v = String(code != null ? code : '').trim().toUpperCase();
    var svOnly = pgIsSupervisorOnlyMenuUrl(pageUrl) && v && v !== 'NONE';
    if (v === 'NONE') return pgAdminUiT('접근불가');
    if (v === 'OBSERVER') return svOnly ? pgAdminUiT('옵저버(SUPERVISOR)') : pgAdminUiT('옵저버(조회만)');
    if (v === 'OBSERVER_HELLO') return svOnly ? pgAdminUiT('옵저버(SUPERVISOR)') : pgAdminUiT('옵저버(헬로)');
    if (v === 'MODIFY') return svOnly ? pgAdminUiT('수정(SUPERVISOR)') : pgAdminUiT('수정(삭제제한)');
    if (v === 'MODIFY_HELLO') return svOnly ? pgAdminUiT('수정(SUPERVISOR)') : pgAdminUiT('수정(헬로)');
    if (v === 'DELETE') return svOnly ? pgAdminUiT('삭제(SUPERVISOR)') : pgAdminUiT('삭제(전체)');
    return pgAdminUiT(String(code || ''));
  }

  function pgPermCellClassList(code, pageUrl) {
    var v = String(code != null ? code : 'NONE').trim().toUpperCase();
    if (v !== 'NONE' && v !== 'OBSERVER' && v !== 'OBSERVER_HELLO' && v !== 'MODIFY' && v !== 'MODIFY_HELLO' && v !== 'DELETE') {
      v = 'DELETE';
    }
    var cls = 'hq-asst-perm-cell hq-asst-perm-cell--' + v;
    if (pgIsSupervisorOnlyMenuUrl(pageUrl) && v !== 'NONE') cls += ' hq-asst-perm-cell--supervisor-only';
    return cls;
  }

  try {
    window.pgIsSupervisorOnlyMenuUrl = pgIsSupervisorOnlyMenuUrl;
    window.pgPermCodeLabel = pgPermCodeLabel;
    window.pgPermCellClassList = pgPermCellClassList;
  } catch (ePgPermEx) { /* ignore */ }

  /** 비활성카드등록 — 등록·해지·수정(본사권한설정 DELETE·MODIFY) */
  function canWriteOpsInactiveCard() {
    var u = getSessionUser();
    if (u && String(u.role || '').toUpperCase() === 'ADMIN') return true;
    var perm = getPagePermissionForUrl('/ops/inactiveCard');
    return perm === 'DELETE' || perm === 'MODIFY' || perm === 'MODIFY_HELLO';
  }

  function canWriteOpsInactiveCardForPane(pane) {
    if (pane && pane._opsIcCanWrite === true) return true;
    if (pane && pane._opsIcCanWrite === false) return false;
    return canWriteOpsInactiveCard();
  }

  function opsIcBrandApi() {
    return window.OPS_INACTIVE_CARD_BRAND || null;
  }

  function opsIcPanDigitsOnly(s) {
    var api = opsIcBrandApi();
    if (api && typeof api.digitsOnly === 'function') return api.digitsOnly(s);
    return String(s == null ? '' : s).replace(/\D/g, '');
  }

  function getOpsInactiveCardRegCardEl(pane) {
    return pane ? pane.querySelector('#opsInactiveCardRegCard') : null;
  }

  function getOpsIcRegPanRow(card, brand) {
    if (!card) return null;
    var api = opsIcBrandApi();
    var layout = api ? api.layoutForBrand(brand) : (brand === 'AMEX' ? 'amex' : 'seg16');
    if (layout === 'amex') return card.querySelector('#opsIcRegPanAmex');
    if (layout === 'diners14') return card.querySelector('#opsIcRegPanDiners');
    return card.querySelector('#opsIcRegPan16');
  }

  function refreshOpsIcRegPanWarn(pane) {
    var card = getOpsInactiveCardRegCardEl(pane);
    if (!card) return;
    var warn = card.querySelector('#opsIcRegPanWarn');
    if (!warn) return;
    var brandSel = card.querySelector('#opsIcRegBrand');
    var brand = brandSel ? String(brandSel.value || '').trim() : '';
    var api = opsIcBrandApi();
    if (!brand || !api) {
      warn.classList.add('d-none');
      warn.textContent = '';
      return;
    }
    var row = getOpsIcRegPanRow(card, brand);
    var pan = api.collectPanFromRow(row);
    var msgKey = api.liveMismatch(brand, pan);
    if (msgKey) {
      warn.textContent = pgAdminUiT(msgKey);
      warn.classList.remove('d-none');
    } else {
      warn.classList.add('d-none');
      warn.textContent = '';
    }
  }

  function applyOpsIcRegPanBrandUi(pane) {
    var card = getOpsInactiveCardRegCardEl(pane);
    if (!card) return;
    var canWrite = pane._opsIcCanWrite !== false;
    var brandSel = card.querySelector('#opsIcRegBrand');
    var pan16 = card.querySelector('#opsIcRegPan16');
    var panAmex = card.querySelector('#opsIcRegPanAmex');
    var panDiners = card.querySelector('#opsIcRegPanDiners');
    var pickHint = card.querySelector('#opsIcRegPanPickHint');
    var warn = card.querySelector('#opsIcRegPanWarn');
    var brand = brandSel ? String(brandSel.value || '').trim() : '';
    if (brandSel) brandSel.disabled = !canWrite;
    card.querySelectorAll('.ops-ic-pan-seg').forEach(function (inp) {
      inp.value = '';
      inp.disabled = true;
    });
    if (pan16) pan16.classList.add('d-none');
    if (panAmex) panAmex.classList.add('d-none');
    if (panDiners) panDiners.classList.add('d-none');
    if (warn) {
      warn.classList.add('d-none');
      warn.textContent = '';
    }
    if (pickHint) pickHint.classList.toggle('d-none', !!brand);
    if (!brand || !canWrite) return;
    var row = getOpsIcRegPanRow(card, brand);
    if (row) {
      row.classList.remove('d-none');
      row.querySelectorAll('.ops-ic-pan-seg').forEach(function (inp) {
        inp.disabled = false;
      });
      var first = row.querySelector('.ops-ic-pan-seg');
      if (first) {
        try { first.focus(); } catch (eFc) {}
      }
    }
  }

  function clearOpsIcRegPanForm(pane) {
    var card = getOpsInactiveCardRegCardEl(pane);
    if (!card) return;
    var maskEl = card.querySelector('#opsIcRegPanMask');
    if (maskEl) maskEl.value = '';
    var holderEl = card.querySelector('#opsIcRegHolderName');
    if (holderEl) holderEl.value = '';
  }

  function normalizeOpsIcMaskInput(raw) {
    var t = String(raw == null ? '' : raw).trim().replace(/\s+/g, '');
    if (!t || t.indexOf('*') < 0) return '';
    var digits = '';
    var suffix = '';
    var inStars = false;
    for (var i = 0; i < t.length; i++) {
      var c = t.charAt(i);
      if (c >= '0' && c <= '9') {
        if (inStars) suffix += c;
        else digits += c;
      } else if (c === '*') inStars = true;
    }
    if (digits.length < 6 || suffix.length < 4) return '';
    return digits.substring(0, 6) + '***' + suffix.substring(suffix.length - 4);
  }

  function collectOpsIcRegPan(pane) {
    var card = getOpsInactiveCardRegCardEl(pane);
    if (!card) return { ok: false, code: 'EMPTY', msgKey: '카드번호(앞 6자리 + *** + 뒤 4자리)를 입력하세요.' };
    var maskEl = card.querySelector('#opsIcRegPanMask');
    var mask = normalizeOpsIcMaskInput(maskEl ? maskEl.value : '');
    if (!mask || !/^\d{6}\*{3}\d{4}$/.test(mask)) {
      return { ok: false, code: 'MASK', msgKey: '카드번호는 앞 6자리 + *** + 뒤 4자리 형식(예: 531289***8601)으로 입력하세요.' };
    }
    return { ok: true, pan: mask, brand: '' };
  }

  function bindOpsIcRegPanUi(pane) {
    var card = getOpsInactiveCardRegCardEl(pane);
    if (!card || card._opsIcPanBound) return;
    card._opsIcPanBound = true;
    var brandSel = card.querySelector('#opsIcRegBrand');
    if (brandSel) {
      brandSel.addEventListener('change', function () {
        applyOpsIcRegPanBrandUi(pane);
        refreshOpsIcRegPanWarn(pane);
      });
    }
    card.addEventListener('input', function (ev) {
      var inp = ev.target;
      if (!inp || !inp.classList || !inp.classList.contains('ops-ic-pan-seg')) return;
      var d = opsIcPanDigitsOnly(inp.value);
      if (d !== inp.value) inp.value = d;
      var max = parseInt(inp.getAttribute('maxlength') || '4', 10);
      if (d.length > max) {
        inp.value = d.substring(0, max);
        d = inp.value;
      }
      if (d.length >= max) {
        var row = inp.closest('.ops-ic-pan-seg-row');
        if (!row) return;
        var segs = row.querySelectorAll('.ops-ic-pan-seg');
        var idx = Array.prototype.indexOf.call(segs, inp);
        if (idx >= 0 && idx < segs.length - 1) {
          try { segs[idx + 1].focus(); } catch (eNx) {}
        }
      }
      refreshOpsIcRegPanWarn(pane);
    });
    card.addEventListener('keydown', function (ev) {
      if (ev.key !== 'Backspace') return;
      var inp = ev.target;
      if (!inp || !inp.classList || !inp.classList.contains('ops-ic-pan-seg')) return;
      if (inp.value) return;
      var row = inp.closest('.ops-ic-pan-seg-row');
      if (!row) return;
      var segs = row.querySelectorAll('.ops-ic-pan-seg');
      var idx = Array.prototype.indexOf.call(segs, inp);
      if (idx > 0) {
        try { segs[idx - 1].focus(); } catch (ePv) {}
        ev.preventDefault();
      }
    });
    card.addEventListener('paste', function (ev) {
      var inp = ev.target;
      if (!inp || !inp.classList || !inp.classList.contains('ops-ic-pan-seg')) return;
      var row = inp.closest('.ops-ic-pan-seg-row');
      if (!row) return;
      var clip = (ev.clipboardData && ev.clipboardData.getData('text')) || '';
      var digits = opsIcPanDigitsOnly(clip);
      if (!digits) return;
      ev.preventDefault();
      var segs = row.querySelectorAll('.ops-ic-pan-seg');
      var start = Array.prototype.indexOf.call(segs, inp);
      if (start < 0) start = 0;
      var pos = 0;
      for (var si = start; si < segs.length && pos < digits.length; si++) {
        var seg = segs[si];
        var max = parseInt(seg.getAttribute('maxlength') || '4', 10);
        seg.value = digits.substring(pos, pos + max);
        pos += max;
      }
      if (pos < digits.length && segs.length) {
        var last = segs[segs.length - 1];
        var lm = parseInt(last.getAttribute('maxlength') || '4', 10);
        last.value = digits.substring(Math.max(0, digits.length - lm));
      }
      var lastFilled = segs[Math.min(segs.length - 1, start + Math.ceil(digits.length / 4) - 1)];
      if (lastFilled) {
        try { lastFilled.focus(); } catch (ePf) {}
      }
      refreshOpsIcRegPanWarn(pane);
    });
    applyOpsIcRegPanBrandUi(pane);
  }

  function opsIcPgVendorOptionLabel(row) {
    var cd = String(row && row.pgCd != null ? row.pgCd : '').trim();
    var nm = String(row && row.pgNm != null ? row.pgNm : '').trim();
    if (nm && cd && nm.toUpperCase() !== cd.toUpperCase()) return nm + ' (' + cd + ')';
    return nm || cd;
  }

  function fillOpsIcPgVendorSelect(sel, selectedValue) {
    if (!sel) return Promise.resolve();
    var keep = selectedValue != null ? String(selectedValue) : String(sel.value || '');
    function applyList(list) {
      var html = '<option value="" data-pg-ui-t="전체 PG">' + pgAdminEscHtml(pgAdminUiT('전체 PG')) + '</option>';
      (list || []).forEach(function (row) {
        var cd = String(row && row.pgCd != null ? row.pgCd : '').trim();
        if (!cd) return;
        var lab = opsIcPgVendorOptionLabel(row);
        html += '<option value="' + String(cd).replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '">' + pgAdminEscHtml(lab) + '</option>';
      });
      sel.innerHTML = html;
      if (keep) {
        var found = false;
        for (var i = 0; i < sel.options.length; i++) {
          if (sel.options[i].value === keep) { found = true; break; }
        }
        if (!found) {
          var o = document.createElement('option');
          o.value = keep;
          o.textContent = keep;
          sel.appendChild(o);
        }
        sel.value = keep;
      }
      if (window.PG_UI_I18N && typeof window.PG_UI_I18N.applyDom === 'function') {
        try { window.PG_UI_I18N.applyDom(sel); } catch (ePgIc) {}
      }
    }
    if (window._pgOpsIcAgencyList) {
      applyList(window._pgOpsIcAgencyList);
      return Promise.resolve();
    }
    if (!window.PG_API || typeof window.PG_API.pgAgencyList !== 'function') {
      applyList([{ pgCd: 'JPAY', pgNm: 'JPAY' }, { pgCd: 'CHILLPAY', pgNm: 'ChillPay' }]);
      return Promise.resolve();
    }
    return window.PG_API.pgAgencyList().then(function (list) {
      window._pgOpsIcAgencyList = Array.isArray(list) ? list : [];
      applyList(window._pgOpsIcAgencyList);
    }).catch(function () {
      applyList([{ pgCd: 'JPAY', pgNm: 'JPAY' }, { pgCd: 'CHILLPAY', pgNm: 'ChillPay' }]);
    });
  }

  function applyOpsInactiveCardWriteUi(pane, canWrite) {
    if (!pane) return;
    pane._opsIcCanWrite = !!canWrite;
    var card = pane.querySelector('#opsInactiveCardRegCard');
    if (card) {
      ['#opsIcRegPanMask', '#opsIcRegHolderName', '#opsIcRegReason', '#opsIcRegPg', '#opsIcRegCompId', '#opsIcRegCompNm', '#opsIcRegBtn'].forEach(function (sel) {
        var el = card.querySelector(sel);
        if (el) el.disabled = !canWrite;
      });
    }
    ['#opsIcReleaseSelectedBtn', '#opsIcReleaseAllBtn'].forEach(function (sel) {
      pane.querySelectorAll(sel).forEach(function (btn) {
        btn.disabled = !canWrite;
        btn.classList.toggle('d-none', !canWrite);
      });
    });
    var hint = pane.querySelector('#opsIcRegPermHint');
    if (hint) hint.classList.toggle('d-none', !!canWrite);
  }

  function collectOpsIcFilterFromPane(pane) {
    var out = {
      searchActiveYn: 'ALL',
      searchKeyword: '',
      searchFromDate: '',
      searchToDate: '',
      searchOrderDir: 'DESC'
    };
    if (!pane) return out;
    var form = pane.querySelector('#screenSearchForm') || pane.querySelector('form');
    if (!form) return out;
    ['searchActiveYn', 'searchKeyword', 'searchFromDate', 'searchToDate'].forEach(function (n) {
      var el = form.querySelector('[name="' + n + '"]') || pane.querySelector('#' + n);
      if (el && el.value) out[n] = String(el.value).trim();
    });
    var dirEl = form.querySelector('[name="searchOrderDir"]') || pane.querySelector('input.screen-list-sort-dir-hidden[name="searchOrderDir"]');
    if (dirEl && dirEl.value) out.searchOrderDir = String(dirEl.value).trim().toUpperCase();
    return out;
  }

  function openOpsIcReleaseModal(pane, tabId, doSearchFn, mode, ids) {
    var releaseModal = ensureOpsInactiveCardReleaseModal();
    if (!releaseModal) return;
    var relMode = mode || 'SINGLE';
    releaseModal._opsIcReleaseContext = {
      pane: pane,
      tabId: tabId,
      doSearchFn: doSearchFn,
      mode: relMode,
      ids: ids || []
    };
    var idEl = releaseModal.querySelector('#opsIcReleaseId');
    var reasonEl = releaseModal.querySelector('#opsIcReleaseReason');
    var otpEl = releaseModal.querySelector('#opsIcReleaseOtp');
    var titleEl = releaseModal.querySelector('#opsIcReleaseModalTitle');
    if (idEl) idEl.value = (relMode === 'SINGLE' && ids && ids.length) ? String(ids[0]) : '';
    if (reasonEl) reasonEl.value = '';
    if (otpEl) otpEl.value = '';
    if (titleEl) {
      var titleKey = relMode === 'SELECTED' ? '선택 카드 해지'
        : (relMode === 'ALL_FILTERED' ? '전체 카드 해지' : '비활성 카드 해지');
      titleEl.setAttribute('data-pg-ui-t', titleKey);
      titleEl.textContent = pgAdminUiT(titleKey);
    }
    if (window.PG_UI_I18N && typeof window.PG_UI_I18N.applyDom === 'function') {
      try { window.PG_UI_I18N.applyDom(releaseModal); } catch (eIcRelI18n) {}
    }
    if (window.bootstrap && window.bootstrap.Modal) {
      window.bootstrap.Modal.getOrCreateInstance(releaseModal).show();
      if (reasonEl) setTimeout(function () { try { reasonEl.focus(); } catch (eF) {} }, 200);
    } else {
      releaseModal.classList.add('show');
      releaseModal.style.display = 'block';
      releaseModal.removeAttribute('aria-hidden');
    }
  }

