        window.PG_API.hqNotifyWebhookPartners ? window.PG_API.hqNotifyWebhookPartners() : Promise.resolve([]),
        window.PG_API.hqNotifyInternalTargets ? window.PG_API.hqNotifyInternalTargets() : Promise.resolve([])
