          tb.innerHTML = '<tr><td colspan="5" class="text-danger small text-center py-3">' + pgAdminEscHtml(pgAdminUiT('정책 목록 API를 사용할 수 없습니다. 페이지를 새로고침하세요.')) + '</td></tr>';
          if (hint) hint.textContent = '';
