              resultSuccessMain: d.resultOk1Ko ? { KOR: d.resultOk1Ko } : {},
              resultSuccessFoot: d.resultOk2Ko ? { KOR: d.resultOk2Ko } : {},
              resultFailMain: d.resultFail1Ko ? { KOR: d.resultFail1Ko } : {},
              resultFailFoot: d.resultFail2Ko ? { KOR: d.resultFail2Ko } : {},
